# Fields: level, unit, title, objective, grammar form, explanation, nuance,
# Japanese illustrative example, kana reading, Traditional Chinese, misconception,
# assessment stem, options, correct index (0-based), why correct.
lessons=[]
def add(L,U,title,objective,form,explain,nuance,ja,kana,zh,caution,q,choices,ans,why):
    assert len(choices)==4
    lessons.append({'id':f'{L.lower()}-c{U}-{sum(x["level"]==L and x["unitId"]==f"{L.lower()}-u{U}" for x in lessons)+1:02d}',
      'level':L,'unitId':f'{L.lower()}-u{U}','title':title,'objective':objective,'pattern':form,
      'explanation':explain,'nuance':nuance,'example':{'ja':ja,'reading':kana,'zh':zh,'provenance':'助理編寫之示例（非來源原文）'},
      'caution':caution,'questions':[{'id':'check-1','prompt':q,'choices':choices,'answerIndex':ans,'explanation':why}],
      'reviewStatus':'editorial_draft','sourceType':'user_document_based'})

# N5 — structure and practical contrast distilled from the actual summary.
add('N5','01','主題助詞 は 與丁寧形 です','區分話題標示與句尾斷定。','A は B です／ではありません','助詞「は」把 A 設為談論主題；「です」表示丁寧的敘述。過去肯定是「でした」，否定常用「ではありません」。','「は」並不等於中文的「是」；肯定與否定的時態由句末承擔。','今日は月曜日です。','きょうはげつようびです。','今天是星期一。','作為助詞的「は」讀作「わ」。','「私は学生ではありません」中「は」的作用是？',['表示動作對象','提示談話主題','表示手段','表示移動方向'],1,'「は」將「私」設為話題；否定在句末「ではありません」。')
add('N5','01','名詞修飾：の','理解 A の B 的所屬、內容與身分。','名詞A＋の＋名詞B','「の」可以表示所有、產地、內容、所屬以及同位關係；前面的 A 修飾後面的 B。','要根據上下文判斷關係，不宜一律機械翻譯成「的」。','これは日本語の本です。','これはにほんごのほんです。','這是日文書。','「友達の田中さん」不必解釋成「朋友擁有田中先生」。','「日本語の本」中的「の」主要表示什麼？',['動作方向','內容／類型','否定','比較'],1,'「日本語」說明書的語言或內容。')
add('N5','01','こそあど：距離與指示','正確區分 これ／この／ここ／こちら。','これ・それ・あれ・どれ／この・その・あの・どの','「これ」等可單獨指物；「この」等必須放在名詞前。場所用「ここ」；較有禮貌的方向與人物介紹可使用「こちら」。','「こ」接近說話者，「そ」接近聽話者或前述資訊，「あ」常指雙方距離遠或共同熟知的事物。','この本は面白いです。','このほんはおもしろいです。','這本書很有趣。','「これ本」不自然；應說「この本」或「これは本です」。','哪一句最自然？',['これ本は面白いです','この本は面白いです','ここ本は面白いです','こちら本は面白いです'],1,'連體詞「この」直接修飾名詞「本」。')
add('N5','02','あります／います：存在表現','依存在對象選擇動詞並標示地點。','場所に＋名詞が＋あります／います','「あります」主要用於物品、植物、抽象事物；「います」主要用於人與動物。存在位置用「に」，存在者常用「が」。','選擇取決於語義和慣用法，並非所有能移動的物品都使用「います」。','庭に猫がいます。','にわにねこがいます。','庭院裡有貓。','將所有「會動」的機械都視為「います」是錯誤的簡化。','「部屋に机が＿＿」應填入？',['あります','います','いきます','きます'],0,'「机」是物品，存在動詞為「あります」。')
add('N5','02','場所助詞 に、で 與受詞 を','分辨存在點、動作場所和受詞。','場所にある／場所で V／名詞を V','「に」標記存在位置或著落點；「で」標記活動發生的場所；「を」典型地標示及物動詞的直接對象。','不能只依「靜態、動態」判斷全部用法；「に／で／を」還有其他語義。','図書館で本を読みます。','としょかんでほんをよみます。','在圖書館看書。','「公園を歩く」的「を」可標示通過的場所，不是直接受詞。','「教室＿＿日本語を勉強します」應填？',['に','で','を','へ'],1,'在教室進行學習活動，使用「で」。')
add('N5','02','移動的 に／へ 與 から／まで','描述目的地、方向與時間範圍。','場所に／へ行く；起點から終點まで','「に」常聚焦抵達點；「へ」表示移動方向。起點使用「から」，終點可用「まで」。','「に」與「へ」在許多移動動詞句裡可互換，但並非所有句型都一樣。','東京から大阪まで電車で行きます。','とうきょうからおおさかまででんしゃでいきます。','從東京搭電車到大阪。','移動手段通常用「で」，並非「へ」。','「東京＿＿大阪まで行きます」表示起點應填？',['から','へ','を','の'],0,'「から」標示起點。')
add('N5','03','い形容詞、な形容詞的變化','區分兩種形容詞的接續與否定。','高い→高くない／静かだ→静かではない','い形容詞依語尾「い」變化；な形容詞連接名詞常需「な」，敬體敘述接「です」。','「きれい」雖以「い」結尾，仍屬な形容詞；「いい」變化常使用「よい」詞幹。','昨日は寒くなかったです。','きのうはさむくなかったです。','昨天不冷。','「きれいくない」錯誤；要說「きれいではない」。','哪一個是「高い」的否定形？',['高いではない','高くない','高なない','高かったない'],1,'い形容詞去「い」接「くない」。')
add('N5','03','比較、最高級與頻率','學習比較級及常用程度語。','A は B より～／一番～／いつも・時々','「より」標示比較基準；「どちら」用於兩者比較；「一番」表示某個範圍內最突出。','程度副詞的選擇與後面敘述的肯否形有搭配習慣，例如「あまり～ない」。','この電車はあの電車より速いです。','このでんしゃはあのでんしゃよりはやいです。','這班電車比那班快。','「あまり」表示不太～時，典型地與否定搭配。','「三つの中で、これが＿＿安いです」應填？',['より','一番','どちら','あまり'],1,'在三者範圍中表示最高程度，使用「一番」。')
add('N5','04','て形：動詞變化與音便','掌握基本的て形與不規則變化。','書く→書いて／泳ぐ→泳いで／行く→行って','五段動詞的て形依結尾音產生不同音便；一段動詞去「る」接「て」。する→して；来る→来て。','「行く」屬常見例外，變「行って」，不是「行いて」。','駅まで歩いて行きます。','えきまであるいていきます。','走路到車站。','看到「く」不能一律變「いて」，要留意慣用例外。','「書く」的て形是哪個？',['書きて','書くて','書いて','書って'],2,'「書く」的標準て形是「書いて」。')
add('N5','04','て形：請求、許可與禁止','會使用日常請求及禮貌禁止。','Vてください／Vてもいい／Vてはいけない','「てください」用於請求；「てもいい」表示許可；「てはいけない」表示不被允許。請求不做某事使用「Vないでください」。','不同形式表示不同交際功能，不能把禁止與勸告當成同義。','ここで写真を撮ってもいいですか。','ここでしゃしんをとってもいいですか。','可以在這裡拍照嗎？','「撮らないでください」是請求不要拍照，不同於「撮ってはいけません」。','「請不要進入」較合適的是？',['入ってください','入ってもいいです','入らないでください','入りました'],2,'否定請求使用「ないでください」。')
add('N5','04','ています：進行與結果狀態','理解同一表達依動詞而有不同讀法。','Vて＋います','活動動詞可表動作正在進行；變化動詞則可能表示變化完成後的結果狀態。','例如「結婚しています」通常表示已婚狀態，而非婚禮正在進行。','窓が開いています。','まどがあいています。','窗戶開著。','「ています」不一定表示正在做動作，要看動詞類型。','「窓が開いています」主要表達？',['正在開窗','窗戶處於開啟狀態','將來要開窗','不能開窗'],1,'「開く」是變化動詞，句中表示結果狀態。')
add('N5','05','た形：經驗與列舉','區分過去事件、人生經驗與例示。','Vたことがあります／VたりVたりします','「たことがある」表示曾有某種經驗；「たり～たり」列舉典型行為，整句時態由後面的「します／しました」決定。','經驗表達不適合取代明確的昨日單次事件敘述。','休みの日は本を読んだり、映画を見たりします。','やすみのひはほんをよんだり、えいがをみたりします。','休假時會看看書、看看電影等等。','列舉的動作不表示已經全部發生。','「日本に行ったことがあります」表示？',['現在正在日本','去過日本','明天要去日本','不能去日本'],1,'「Vたことがある」表示既有經驗。')
add('N5','05','ない形與勸告','能提出做或不做某事的建議。','Vたほうがいい／Vないほうがいい','「Vたほうがいい」常表示最好採取某行動；「Vないほうがいい」表示最好避免。','這是建議，不等於法律上的強制義務。','疲れているなら、早く寝たほうがいいです。','つかれているなら、はやくねたほうがいいです。','如果累了，最好早點睡。','「ないほうがいい」需要否定形，不是「ないでほう」。','「最好不要熬夜」如何表達？',['夜更かししたほうがいい','夜更かししないほうがいい','夜更かしすることがあります','夜更かししています'],1,'避免某動作的建議是「Vないほうがいい」。')
add('N5','06','あげる、もらう、くれる','依誰給誰、誰受益選擇授受動詞。','AがBにあげる／AがBにもらう／Aが私にくれる','「あげる」從給予方描述；「もらう」從收受方描述；「くれる」常表示他人給予說話者或其心理內團體成員。','授受動詞依說話者視角而選擇，不能只看箭頭方向。','友達が私に本をくれました。','ともだちがわたしにほんをくれました。','朋友送了我一本書。','敘述不熟悉第三人之間的授受時，需要注意「くれる」的視角。','「朋友送我一本書」自然的動詞是？',['あげました','くれました','しまいました','なりました'],1,'站在受益方「我」的視角，可使用「くれる」。')
add('N5','06','てあげる、てもらう、てくれる','將授受觀念延伸為他人做某事的恩惠。','Vて＋あげる／もらう／くれる','「てあげる」為別人做；「てもらう」得到別人提供的協助；「てくれる」表示他人為我方做。','面對上司或陌生人時，「てあげる」可能顯得居高臨下，宜依情境選詞。','先生が説明してくれました。','せんせいがせつめいしてくれました。','老師為我說明了。','文法上的「給予恩惠」不代表每個情境都必然含感恩情緒。','「同事幫我修好電腦」要凸顯我得到協助，可用？',['直してくれました','直してあげました','直しなさい','直すはずです'],0,'「てくれる」描寫對方為我方提供協助。')

# N4
add('N4','01','可能形：能力和條件','把動詞轉為表示做得到的形式。','書く→書ける／食べる→食べられる','五段動詞改為エ段＋る，一段動詞去る加られる，する→できる，来る→来られる。','可能表達可用「が」標示對象，但某些情境也能使用「を」，不能說一律禁止「を」。','私は日本語が話せます。','わたしはにほんごがはなせます。','我會說日文。','可能形與受身形同形時，需靠語境判別。','「読む」的可能形？',['読まれる','読める','読ませる','読もう'],1,'五段動詞「読む」變「読める」。')
add('N4','01','受身形：直接與間接受身','分清行為的接受者與間接受影響者。','Vれる／Vられる','直接受身把受動作影響的人事物放在主語；間接受身有時傳達困擾，如「雨に降られた」。','不是所有被動句都含受害、抱怨；報導、客觀描寫也常使用受身形。','この本は多くの人に読まれています。','このほんはおおくのひとによまれています。','這本書受到許多人閱讀。','不要把「被動」等同「不幸」。','「私は弟にケーキを食べられた」最可能含有？',['自己吃蛋糕','弟弟替我買蛋糕','自己的蛋糕被弟弟吃掉的困擾','弟弟請我吃蛋糕'],2,'間接受身可能表達自己受到影響。')
add('N4','01','使役形：要求、容許、使其發生','分辨使役句是強制還是許可。','書く→書かせる／食べる→食べさせる','五段動詞改あ段＋せる，一段動詞去る加させる。實際是要求、允許或造成某動作，須看情境。','「使役」並不必然是階級強迫；也可表允許與培養。','母は子どもにピアノを習わせました。','はははこどもにピアノをならわせました。','母親讓孩子學鋼琴。','應依語境判斷是要求還是許可，單靠句型不一定能確定。','「飲む」的使役形？',['飲める','飲まれる','飲ませる','飲んだ'],2,'「飲む」變「飲ませる」。')
add('N4','01','條件：ば、たら、なら、と','理解條件句在一般規律與假設中的差異。','行けば／行ったら／行くなら／行くと','「と」常描述規律或自然結果；「たら」彈性較高；「なら」可回應先前提出的前提；「ば」表示條件成立後的結果。','「ば」不是一律不能接命令或邀請；是否自然還受主語、條件內容影響。','時間があれば、ぜひ来てください。','じかんがあれば、ぜひきてください。','如果有時間，請務必來。','不要把四種條件形當成語義完全相等的替換。','「春になると、桜が咲く」的「と」常表示？',['自然規律','過去習慣的否定','敬語請求','因果責任'],0,'「と」可表示條件一成立就出現的規律性結果。')
add('N4','02','意志強度：ようと思う・つもり・予定','比較意向、打算與已安排的計畫。','Vようと思う／Vるつもり／Vる予定','「ようと思う」表思考或意向；「つもり」表示打算；「予定」常用於已安排的行程。','這是常見語意傾向，不表示每種形式只有一個固定心理強度。','来月、日本へ行く予定です。','らいげつにほんへいくよていです。','預定下個月去日本。','是否已經訂票或決定，不能單靠句型百分百推定。','「已排入行程」較常見的是？',['行く予定です','行きたがっています','行かされます','行くそうです'],0,'「予定」常標示安排或預定。')
add('N4','02','ことにする／ことになる','區分主動決定與外部決定。','Vる／Vない＋ことにする／ことになる','「ことにする」重在說話者做出的決定；「ことになる」多表示經過協議、制度或情勢而形成的結果。','「ことになる」不必然代表毫無個人意志，也可描述共同決議。','来年から日本で働くことになりました。','らいねんからにほんではたらくことになりました。','已經決定從明年開始在日本工作。','不要把「ことになった」自動翻成「被逼迫」。','哪句最直接表達「我自己決定」？',['転職することにしました','転職することになりました','転職したら','転職するそうです'],0,'「ことにする」通常著重個人決定。')
add('N4','02','ようになる與授受敬語','描述變得能做，以及禮貌地接受協助。','V可能＋ようになる／Vていただく','「ようになる」描述能力、習慣或狀態改變；「ていただく」是「てもらう」的謙讓形式，尊重提供協助者。','它們用途不同，課文將兩者同列在主觀與人際表達範圍。','先生に説明していただきました。','せんせいにせつめいしていただきました。','承蒙老師向我說明。','「いただく」的主語視角與「くださる」不同。','「日本語が読める＿＿」表示能力獲得？',['そうです','ようになりました','ことにします','たところです'],1,'「可能形＋ようになる」表示變得能做到。')
add('N4','03','樣態そうだ與傳聞そうだ','依訊息來源選擇接續。','おいしそうだ／雨が降るそうだ','樣態「そう」接詞幹或ます形去ます，表看起來～；傳聞「そう」接普通形，表聽說～。','兩者看起來同形，但接續和證據來源不同。','天気予報によると、明日は雨が降るそうです。','てんきよほうによるとあしたはあめがふるそうです。','根據天氣預報，聽說明天會下雨。','形容詞「いい」的樣態形式是「よさそう」，不是「いそう」。','「おいしそう」的「そう」主要表示？',['傳聞','外觀看來','原因','義務'],1,'樣態「そう」依外觀推測。')
add('N4','03','ようだ、みたいだ、らしい','比較比況、推測與傳聞印象。','V普通形＋ようだ／みたいだ／らしい','「ようだ」與「みたいだ」可表示依線索的推測與比況；「らしい」常用於傳聞或典型特徵的判斷。','這三種形式語義範圍部分重疊，不能給予固定的百分百確定度。','外が濡れています。雨が降ったようです。','そとがぬれています。あめがふったようです。','外面濕了，似乎下過雨。','「らしい」也可表示符合典型性，如「子どもらしい」。','「田中さんらしい服」較可能表示？',['田中先生特有的風格','田中先生已換衣服','田中先生命令','田中先生的衣服壞了'],0,'「らしい」有符合典型特徵的用法。')
add('N4','03','ながら・すぎる・しかない','用一個句子表示並行、超量或限定。','Vます去ます＋ながら／すぎる；Nしか＋否定','「ながら」常表示同一主體動作同時進行；「すぎる」表示過度；「しか～ない」突出選擇或數量有限。','「しか」要有否定述語，與「だけ」形式不同。','ここには一人しかいません。','ここにはひとりしかいません。','這裡只有一個人。','「食べすぎる」表示吃太多，不必然含道德批判。','「100円しか＿＿」最自然的是？',['あります','ありません','ありました','あるでしょう'],1,'「しか」需與否定搭配。')
add('N4','04','尊敬語、謙讓語、丁寧語','依誰的行為選擇合適敬語。','お／ご～になる・お／ご～する・です／ます','尊敬語抬高主體或行為者；謙讓語透過自己一方的行為表示對對方的敬意；丁寧語使整句禮貌。','敬語選擇還受內外關係與交際場合影響，非純粹上下級公式。','部長はもうお帰りになりました。','ぶちょうはもうおかえりになりました。','部長已經回去了。','敬語有不規則形式，如「いらっしゃる」「申す」。','「部長がお読みになる」屬於？',['謙讓語','尊敬語','普通形','命令形'],1,'「お～になる」是常見尊敬語形式。')

# N3 — document is missing an independent chapter 2; do not create it.
add('N3','01','口語縮約：ちゃう／じゃう','認識「てしまう」在口語中的變化。','Vてしまう→Vちゃう；Vでしまう→Vじゃう','口語縮約常用於熟悉、非正式場合；基本語意仍含動作完成或遺憾。','縮約形並不必然代表親密關係，正式報告和書面文通常避免使用。','宿題を忘れちゃった。','しゅくだいをわすれちゃった。','不小心忘記作業了。','不是所有「ちゃう」都只是負面情緒，它也可能表完成。','「飲んでしまった」的口語縮約？',['飲んちゃった','飲んじゃった','飲んといた','飲みてる'],1,'「でしまう」常縮成「じゃう」。')
add('N3','01','縮約：とく、てる、ちゃいけない','區分預先準備、持續狀態與禁止。','ておく→とく／ている→てる／てはいけない→ちゃいけない','「とく」是預先處理，「てる」是不完整寫法的口語縮約，「ちゃいけない」是口語禁止。','在教學上須先掌握原形式再理解縮略形式；不能在所有正式場合直接使用。','明日の資料を準備しとく。','あしたのしりょうをじゅんびしとく。','先準備明天的資料。','不要把「しとく」當成另一種全新動詞活用類別。','「待っておく」的口語形式？',['待ってる','待っとく','待っちゃう','待ってみる'],1,'「ておく」縮成「とく」。')
add('N3','01','書面語：である、において','將口語或丁寧敘述轉為正式書面表達。','である／名詞＋において／名詞＋における＋名詞','「である」常見於學術及報導式敘述；「において」標示場合、領域與時間；連體修飾時用「における」。','它們較正式，但不代表說話內容必然客觀正確或不可反駁。','日本市場における需要を調査する。','にほんしじょうにおけるじゅようをちょうさする。','調查日本市場中的需求。','「における」要修飾後面的名詞，而「において」後接述語。','「学校＿＿教育」應選？',['において','における','によると','につれて'],1,'修飾名詞「教育」時使用「における」。')
add('N3','01','ともに／に伴って：關係與變化','理解伴隨與共同發生，不把兩者視為同義。','名詞＋とともに／に伴って','「とともに」可表同時或共同；「に伴って」常描述伴隨變動而發生的變化。','「に伴って」不是在每個句子中都斷言已證明的因果；常只表示相關或伴隨。','人口が増えるにつれて、住宅も増えている。','じんこうがふえるにつれてじゅうたくもふえている。','隨著人口增加，住宅也增加。','例句採相近的「につれて」幫助對照，同時參照文法庫的正式接續。','「景気の回復に伴って」最接近？',['與景氣復甦無關','隨著景氣復甦','因為景氣必定崩盤','不論景氣如何'],1,'「に伴って」表伴隨變化。')
add('N3','02','わけだ／わけがない','透過理由做歸納或強烈否定。','普通形＋わけだ／わけがない','「わけだ」可表示理解原因後「難怪」或推論結果；「わけがない」表示依理由判斷不可能。','「わけがない」是強烈主觀判斷，不是形式邏輯上不可反駁的證明。','毎日練習しているんですね。上手なわけです。','まいにちれんしゅうしているんですね。じょうずなわけです。','原來每天都在練習，難怪那麼厲害。','「わけではない」是部分否定，與「わけがない」不同。','「その値段で買えるわけがない」表示？',['買得起','不可能買得起','理應買到','打算買'],1,'「わけがない」表強烈的不可能判斷。')
add('N3','02','はずだ／に違いない','根據預期或線索表達較強判斷。','普通形＋はずだ／に違いない','「はずだ」常根據已知資訊形成預期；「に違いない」帶有說話者確信的推斷。','不應把這兩者變成固定的百分比確信度或「絕對真理」。','電車はもう着いたはずです。','でんしゃはもうついたはずです。','電車按理應該已經到了。','「はずだった」與實際結果不符時，常有落差的語氣。','「按時刻表，車現在應該到了」較符合？',['着いたはずだ','着いてはいけない','着くしかない','着いてしまう'],0,'既有資訊支持的預期可用「はずだ」。')
add('N3','03','きる、きれない、抜く','比較完成、無法完成和堅持到底。','Vます去ます＋きる／きれない／抜く','「きる」強調做到最後；「きれない」表示無法全部完成；「抜く」常表示忍受困難而堅持完成。','三者不都是「努力」的同義詞；「きる」也能用於耗盡或程度很高的情況。','この料理は量が多くて食べきれない。','このりょうりはりょうがおおくてたべきれない。','這份料理太多，吃不完。','「食べられない」是不能吃，「食べきれない」是無法全部吃完。','「最後まで走り＿＿」表示堅持跑完全程？',['きる','かける','たて','っぱなし'],0,'「走りきる」表示跑到最後。')
add('N3','03','かける、たて、っぱなし','描述進行未完、剛完成及狀態放置。','Vます去ます＋かける／たて／っぱなし','「かける」可表示動作做到一半；「たて」表示剛完成的狀態；「っぱなし」表示一個狀態一直未處理。','「っぱなし」常有不滿或疏忽的語感，但也能客觀描述狀態。','電気をつけっぱなしで出かけた。','でんきをつけっぱなしででかけた。','燈沒關就出門了。','「読みかけの本」是讀到一半的書，不是新出版的書。','「焼き＿＿のパン」表示剛烤好的麵包？',['っぱなし','たて','きれない','ながら'],1,'「焼きたて」表示剛烤好。')
add('N3','04','こそ、さえ：強調與極端例示','理解聚焦與「連……都」的用法。','名詞＋こそ／さえ','「こそ」強調一個焦點，「さえ」可以舉極端事例，表示連最低限度的條件都無法達成，或「只要～就～」。','「さえ」有多種接續形式，不能只用一個中文譯法套在全部句子上。','彼は自分の名前さえ書けない。','かれはじぶんのなまえさえかけない。','他連自己的名字都寫不出來。','「さえ～ば」與「さえ～ない」的邏輯功能不同。','「今日こそ」常表示？',['今天也不重要','正是今天','不要今天','昨天才是'],1,'「こそ」加強焦點「今天」。')
add('N3','04','だらけ、がち、気味','區分充滿、易於發生與稍有傾向。','名詞＋だらけ／Vます去ます＋がち／名詞＋気味','「だらけ」常表示充滿不理想的事物；「がち」表示某種傾向常發生；「気味」表示有點那樣的感覺或狀態。','「気味」比一般斷定更保留餘地；不能把所有「がち」直接翻成一定會發生。','最近、少し疲れ気味です。','さいきんすこしつかれぎみです。','最近稍微有點累。','「ほこりだらけ」常帶負面評價，不等於單純「很多灰塵」的中性說法。','「遅れがち」最接近哪種意思？',['常常容易遲到','絕不遲到','剛遲到一次','必須遲到'],0,'「がち」表示容易出現某種傾向。')

# N2
add('N2','01','に際して・にあたって・を皮切りに','區分重要場合、著手時及一連串事件的開始。','N＋に際して／N＋にあたって／N＋を皮切りに','前兩種常用於重要事件或正式場合，後者常表示某件事為一系列活動的開端。','「に際して」並非每次都需要儀式；「にあたって」不必然含積極情緒。','新店舗の開業にあたって、説明会を開いた。','しんてんぽのかいぎょうにあたってせつめいかいをひらいた。','在新店開幕之際舉辦了說明會。','「皮切り」需要有後續連續發生的語境。','「東京公演＿＿、全国ツアーが始まった」應填？',['を皮切りに','にすぎない','ざるを得ない','ものなら'],0,'從東京公演開始一系列巡迴演出，可用「を皮切りに」。')
add('N2','01','たとたん・かと思うと・次第','辨別突然、迅速連續與一旦完成就執行。','Vた＋とたん／Vた＋かと思うと／Vます去ます＋次第','「たとたん」表示緊接著發生的意外變化；「かと思うと」表示前後兩個狀態迅速交替；「次第」可表示一旦前項完成便做後項。','「次第」在商務文中常見，但也可在其他正式場合使用。','結果が分かり次第、ご連絡します。','けっかがわかりしだいごれんらくします。','結果一出來就聯絡您。','「とたん」後句通常不適合接明顯可由自己自由控制的意志計畫。','「資料が届き＿＿、お送りします」應填？',['次第','ものの','ほど','きり'],0,'「Vます去ます＋次第」表示前項一完成立即進行後項。')
add('N2','01','つつある・ながらも','閱讀趨勢變化及轉折並存。','Vます去ます＋つつある／普通形・名詞＋ながらも','「つつある」常表變化正在進行；「ながらも」表示雖處於前項狀態，仍出現反預期的後項。','「つつある」不是可以直接取代所有「ている」的書面版本。','景気は少しずつ回復しつつある。','けいきはすこしずつかいふくしつつある。','景氣正逐步復甦。','「ながらも」不同於單純同時做兩個動作的「ながら」。','「回復しつつある」表示？',['復甦正在進行','完全沒有變化','已全面停止','明令禁止'],0,'「つつある」表示變化過程仍在進行。')
add('N2','02','上は・からには・以上は','理解既定前提與決心、義務的連結。','普通形＋からには／以上は；Vた＋上は','三者都可表「既然～就～」，實際語氣與書面程度不同，後項常跟責任、決意或應當承擔的事。','原整理所談的「主觀／客觀強度」是常見傾向，不是三者絕不能互換的鐵律。','約束したからには、最後までやり抜きます。','やくそくしたからにはさいごまでやりぬきます。','既然答應了，就會堅持到底。','「上は」與「上で」不是相同句型。','「決めた＿＿、責任を持つ」最合適？',['からには','ばかり','がち','かねる'],0,'「決めたからには」表既然做出決定，就承擔結果。')
add('N2','02','を問わず・にかかわらず・限り','限制與取消限制的不同功能。','N＋を問わず／N＋にかかわらず／V普通形＋限り','「を問わず」忽略特定分類，「にかかわらず」表示不受某條件影響；「限り」可設定條件持續的範圍。','「限り」不必然導出絕對真理，依後項時態與主觀判斷而定。','年齢を問わず、参加できます。','ねんれいをとわずさんかできます。','不分年齡都能參加。','「にかかわらず」可處理對立條件，不要與「にもかかわらず」逆接混淆。','「天候＿＿試合を行う」表示不管天氣如何？',['にかかわらず','に反して','を皮切りに','に基づいて'],0,'「にかかわらず」表示條件不影響結果。')
add('N2','02','ざるを得ない・ほかない・ようがない','區分無奈的義務、僅剩選項與沒有方法。','Vない形去ない＋ざるを得ない／Vる＋ほかない／Vます去ます＋ようがない','「ざるを得ない」表示不得不做；「ほかない」表示別無選擇；「ようがない」表示缺乏具體方法、手段。','「ざるを得ない」常含無奈，但不是法律上不可抗力的專用詞。','資料がないので、調べようがありません。','しりょうがないのでしらべようがありません。','因為沒有資料，無從調查。','「する」的不規則形式是「せざるを得ない」。','「連絡先がなくて、連絡し＿＿」表示沒有辦法？',['ようがない','きれない','つつある','しかない'],0,'「Vます去ます＋ようがない」表示沒有可行方法。')
add('N2','03','反面・一方で・とはいえ','比較事物兩面與承認前提的讓步。','N＋の反面／一方で／普通形＋とはいえ','「反面」聚焦事物正反兩面，「一方で」常並列相對不同的面向；「とはいえ」先承認前項，再補入保留或反對意見。','不能將「反面」「一方で」全部理解為嚴格因果反轉。','便利な反面、費用が高い。','べんりなはんめんひようがたかい。','雖然方便，但另一方面費用很高。','「とはいえ」可承認前句為事實後再提出限制。','「便利な＿＿、費用が高い」適合哪個？',['反面','次第','おそれ','きり'],0,'「反面」可描寫同一件事的另一面。')
add('N2','03','に反して・どころか・にしても','處理預期違背、強烈否定和假設讓步。','N＋に反して／普通形＋どころか／普通形＋にしても','「に反して」表示與預測、期待或規則相反；「どころか」推翻較弱的預期並強調實際情形；「にしても」先承認或假設前項。','「どころか」須依文意判斷是升級還是降級的出乎意料。','予想に反して、試験は簡単だった。','よそうにはんしてしけんはかんたんだった。','與預期相反，考試很簡單。','「にもかかわらず」與「にかかわらず」是不同句型。','「予定＿＿、結果が良かった」表示出乎預期？',['に反して','を問わず','に基づいて','に応じて'],0,'「に反して」表示與原先預測相反。')
add('N2','04','にきまっている・にすぎない・にほかならない','比較強烈斷定、低估與排他性認定。','普通形＋にきまっている／N＋にすぎない／N＋にほかならない','「にきまっている」表示主觀上確信；「にすぎない」貶低程度或限定；「にほかならない」強調就是某種本質或原因。','語氣強弱是語用差異，不代表客觀證據一定較多。','これは単なる偶然にすぎない。','これはたんなるぐうぜんにすぎない。','這只不過是偶然而已。','對正式論文而言，不要以「にきまっている」替代證據。','「只是偶然」較自然的說法？',['偶然にすぎない','偶然を問わず','偶然次第','偶然に際して'],0,'「にすぎない」表示只不過是～。')
add('N2','04','ないではいられない・をめぐって・に基づく','理解難以抑制的反應、爭議焦點與依據。','Vないではいられない／N＋をめぐって／N＋に基づく','「ないではいられない」表示忍不住；「をめぐって」表示圍繞某問題；「に基づく」表示有明確的依據或基礎。','「に基づく」是有依據的形式，不代表該依據必然真實或充分。','調査結果に基づいて、計画を変更した。','ちょうさけっかにもとづいてけいかくをへんこうした。','根據調查結果修改了計畫。','「をめぐって」多與意見、爭論、事件、情勢等搭配。','「資料＿＿報告を書く」表示依據資料？',['に基づいて','を皮切りに','にすぎない','しかない'],0,'「に基づいて」表示以材料作為依據。')
add('N2','05','おそれがある・かねない','區分客觀風險表述與負面可能性的推測。','Vる／Nの＋おそれがある／Vます去ます＋かねない','「おそれがある」常見於報告或公告，提示不利事件風險；「かねない」表示可能導致不好的結果。','不能將這兩者當作已經確定會發生的事實。','大雨で電車が遅れるおそれがあります。','おおあめででんしゃがおくれるおそれがあります。','因大雨，電車可能延誤。','「かねる」表示難以做到，與「かねない」不能混淆。','「大きな事故が起きる＿＿」應填？',['おそれがある','ことになる','きりだ','に際して'],0,'「おそれがある」常用於負面風險預告。')
add('N2','05','がたい・得ない・こと／まい','理解難以接受、不可能與正式的義務語氣。','Vます去ます＋がたい／得ない／Vる＋まい／指示＋こと','「がたい」常表示心理上或性質上難以做到；「得ない」表示不可能；規章句尾「こと」表要求；「まい」可表否定推測或不做某事的決心。','「がたい」不是所有物理不可能的通用形式；「まい」的接續和意思需依句型辨別。','この説明には納得しがたい。','このせつめいにはなっとくしがたい。','這個說明令人難以接受。','命令性「～こと」常見於規章，不等於所有名詞化「こと」都在命令。','「規則を守る＿＿」作公告指示？',['こと','がち','からには','どころか'],0,'句末「こと」可用於正式規章或書面指示。')

assert len(lessons)>35,len(lessons)
# Detect page numbers in provided source PDFs; docx has no stable PDF pagination.
chapters=[]
for level,defs in unitdef.items():
    file=sourceFiles[level]
    pdfpages=[]
    if file.endswith('.pdf'):
        d=fitz.open(root/'SOURCE_MATERIALS'/file)
        pdfpages=[pg.get_text().replace(' ','').replace('\n','') for pg in d]
    for unitnum,title,orig in defs:
        pref=orig[:16].replace(' ','')
        pages=[i+1 for i,txt in enumerate(pdfpages) if pref in txt]
        page=pages[0] if pages else None
        # deterministic fallback from chapter tokens only; do not claim a page if unsupported
        cid=f'{level.lower()}-u{unitnum}'
        chapters.append({'id':cid,'level':level,'title':title,'sourceChapter':orig,'sourceFile':file,'sourcePage':page,
            'lessonIds':[x['id'] for x in lessons if x['unitId']==cid]})
        for l in lessons:
            if l['unitId']==cid:
                l['source']={'filename':file,'section':orig,'pdfPage':page,
                  'note':'由使用者提供的總整理之相關主題改寫；規則與例句採教學化重述，非原文逐字轉錄。'}
sourceMeta={L:{'name':sourceFiles[L],'materialType':'docx' if L=='N3' else 'pdf','status':'not_teacher_reviewed'} for L in sourceFiles}
result={'version':'0.4.2','editorialMethod':'lesson-based original pedagogical rewrite with sourced chapter mapping',
    'reviewStatus':'pending_language_teacher_review', 'sourceMaterial':sourceMeta,'units':chapters,'lessons':lessons}
out=root/'src/data/grammar-courses.json'
out.write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
print('Courses:',len(chapters),'Lessons:',len(lessons),'Checks:',sum(len(x['questions']) for x in lessons))
print('By level:',{lv:(len([x for x in chapters if x['level']==lv]),len([x for x in lessons if x['level']==lv])) for lv in sourceFiles})
print('Missing exact source PDF chapter matches:',[(x['level'],x['sourceChapter'][:35]) for x in chapters if x['sourcePage'] is None])
